// src/modules/core-business/index.ts
async function resolveIdProducto(referencia, connection) {
  if (typeof referencia === "number") {
    throw new Error(
      `La referencia va como texto, entre comillas: "referencia": "${referencia}". Escrita como n\xFAmero pierde los ceros a la izquierda y podr\xEDa ser la de otro producto.`
    );
  }
  if (typeof referencia !== "string" || referencia.trim() === "") {
    throw new Error(
      "Indica la referencia o el idproducto del producto: sin ninguno de los dos no se sabe qu\xE9 producto modificar o eliminar."
    );
  }
  const productos = await fsClient.get(
    "/productos",
    { referencia, limit: 1 },
    connection
  );
  const producto = Array.isArray(productos) ? productos[0] : void 0;
  if (!producto) {
    throw new Error(`No se encontr\xF3 ning\xFAn producto con la referencia "${referencia}".`);
  }
  if (typeof producto.referencia !== "string" || producto.referencia.toLowerCase() !== referencia.toLowerCase()) {
    throw new Error(
      `Al buscar la referencia "${referencia}" la API ha devuelto otro producto ("${producto.referencia ?? "sin referencia"}"); no se modifica ni se elimina nada.`
    );
  }
  return producto.idproducto;
}
