async function registerFinanceTools(tools5) {
  financeTools.forEach((tool) => tools5.set(tool.name, tool));
  financeWriteTools.forEach((tool) => tools5.set(tool.name, tool));
}
async function handleFinanceTool(name, args) {
  const input = args;
  switch (name) {
    case "get_cuentabancos": {
      const params = input;
      const result = await fsClient.get(
        "/cuentabancos",
        {
          offset: params.offset,
          limit: params.limit,
          codcuenta: params.codcuenta
        },
        params.connection
      );
      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }]
      };
    }
    case "get_formapagos": {
      const params = input;
      const result = await fsClient.get(
        "/formapagos",
        {
          offset: params.offset,
          limit: params.limit,
          codpago: params.codpago
        },
        params.connection
      );
      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }]
      };
    }
    case "get_divisas": {
      const params = input;
      const result = await fsClient.get(
        "/divisas",
        {
          offset: params.offset,
          limit: params.limit,
          coddivisa: params.coddivisa
        },
        params.connection
      );
      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }]
      };
    }
    case "get_retenciones": {
      const params = input;
      const result = await fsClient.get(
        "/retenciones",
        {
          offset: params.offset,
          limit: params.limit,
          codretencion: params.codretencion
        },
        params.connection
      );
      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }]
      };
    }
    case "get_impuestos": {
      const params = input;
      const result = await fsClient.get(
        "/impuestos",
        {
          offset: params.offset,
          limit: params.limit,
          codimpuesto: params.codimpuesto
        },
        params.connection
      );
      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }]
      };
    }
    case "get_impuestozonas": {
      const params = input;
      const result = await fsClient.get(
        "/impuestozonas",
        {
          offset: params.offset,
          limit: params.limit
        },
        params.connection
      );
      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }]
      };
    }
    case "get_regularizacionimpuestos": {
      const params = input;
      const result = await fsClient.get(
        "/regularizacionimpuestos",
        {
          ...dateRangeFilters("get_regularizacionimpuestos", input),
          offset: params.offset,
          limit: params.limit,
          codejercicio: params.codejercicio
        },
        params.connection
      );
      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }]
      };
    }
    case "create_formapago": {
      const params = input;
      const { connection, ...data } = params;
      const result = await fsClient.post("/formapagos", data, connection);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }
    case "update_formapago": {
      const params = input;
      const { connection, codpago, ...data } = params;
      const result = await fsClient.put(`/formapagos/${pathCode(codpago, "codpago")}`, data, connection);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }
    case "delete_formapago": {
      const params = input;
      const result = await fsClient.delete(`/formapagos/${pathCode(params.codpago, "codpago")}`, params.connection);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }
    case "create_divisa": {
      const params = input;
      const { connection, ...data } = params;
      const result = await fsClient.post("/divisas", data, connection);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }
    case "update_divisa": {
      const params = input;
      const { connection, coddivisa, ...data } = params;
      const result = await fsClient.put(`/divisas/${pathCode(coddivisa, "coddivisa")}`, data, connection);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }
    case "delete_divisa": {
      const params = input;
      const result = await fsClient.delete(`/divisas/${pathCode(params.coddivisa, "coddivisa")}`, params.connection);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }
    case "create_impuesto": {
      const params = input;
      const { connection, ...data } = params;
      const result = await fsClient.post("/impuestos", data, connection);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }
    case "update_impuesto": {
      const params = input;
      const { connection, codimpuesto, ...data } = params;
      const result = await fsClient.put(`/impuestos/${pathCode(codimpuesto, "codimpuesto")}`, data, connection);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }
    case "delete_impuesto": {
      const params = input;
      const result = await fsClient.delete(`/impuestos/${pathCode(params.codimpuesto, "codimpuesto")}`, params.connection);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }
    case "create_retencion": {
      const params = input;
      const { connection, ...data } = params;
      const result = await fsClient.post("/retenciones", data, connection);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }
    case "update_retencion": {
      const params = input;
      const { connection, codretencion, ...data } = params;
      const result = await fsClient.put(`/retenciones/${pathCode(codretencion, "codretencion")}`, data, connection);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }
    case "delete_retencion": {
      const params = input;
      const result = await fsClient.delete(`/retenciones/${pathCode(params.codretencion, "codretencion")}`, params.connection);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }
    default:
      return null;
  }
}

