async function registerConfigurationTools(tools5) {
  configurationTools.forEach((tool) => tools5.set(tool.name, tool));
  configurationWriteTools.forEach((tool) => tools5.set(tool.name, tool));
}
async function handleConfigurationTool(name, args) {
  const connection = args.connection || void 0;
  const offset = args.offset || 0;
  const limit = args.limit || 100;
  try {
    let result;
    switch (name) {
      case "get_series": {
        const params = { offset, limit };
        if (args.codserie) params.codserie = args.codserie;
        if (args.tipodoc) params.tipodoc = args.tipodoc;
        result = await fsClient.get("/series", params, connection);
        break;
      }
      case "get_secuenciadocumentos": {
        result = await fsClient.get("/secuenciadocumentos", { offset, limit }, connection);
        break;
      }
      case "get_formatodocumentos": {
        result = await fsClient.get("/formatodocumentos", { offset, limit }, connection);
        break;
      }
      case "get_estadodocumentos": {
        const params = { offset, limit };
        if (args.tipodoc) params.tipodoc = args.tipodoc;
        result = await fsClient.get("/estadodocumentos", params, connection);
        break;
      }
      case "get_doctransformations": {
        result = await fsClient.get("/doctransformations", { offset, limit }, connection);
        break;
      }
      case "get_pagefilteres": {
        result = await fsClient.get("/pagefilteres", { offset, limit }, connection);
        break;
      }
      case "get_pages": {
        result = await fsClient.get("/pages", { offset, limit }, connection);
        break;
      }
      case "get_totalmodeles": {
        result = await fsClient.get("/totalmodeles", { offset, limit }, connection);
        break;
      }
      case "get_identificadorfiscales": {
        result = await fsClient.get("/identificadorfiscales", { offset, limit }, connection);
        break;
      }
      case "get_empresas": {
        result = await fsClient.get("/empresas", { offset, limit, ...dateRangeFilters("get_empresas", args) }, connection);
        break;
      }
      case "get_apiaccess": {
        result = await fsClient.get("/apiaccess", { offset, limit }, connection);
        break;
      }
      case "get_apikeyes": {
        result = await fsClient.get("/apikeyes", { offset, limit, ...dateRangeFilters("get_apikeyes", args) }, connection);
        break;
      }
      case "get_agenciatransportes": {
        result = await fsClient.get("/agenciatransportes", { offset, limit }, connection);
        break;
      }
      case "get_pageoptions": {
        const params = { offset, limit, ...dateRangeFilters("get_pageoptions", args) };
        if (args.name) params.name = args.name;
        if (args.nick) params.nick = args.nick;
        result = await fsClient.get("/pageoptions", params, connection);
        break;
      }
      case "get_settings": {
        const params = { offset, limit };
        if (args.name) params.name = args.name;
        result = await fsClient.get("/settings", params, connection);
        break;
      }
      case "create_serie": {
        const { connection: _conn, ...data } = args;
        result = await fsClient.post("/series", data, connection);
        break;
      }
      case "update_serie": {
        const { connection: _conn, codserie, ...data } = args;
        result = await fsClient.put(`/series/${pathCode(codserie, "codserie")}`, data, connection);
        break;
      }
      case "delete_serie": {
        result = await fsClient.delete(`/series/${pathCode(args.codserie, "codserie")}`, connection);
        break;
      }
      case "create_empresa": {
        const { connection: _conn, ...data } = args;
        result = await fsClient.post("/empresas", data, connection);
        break;
      }
      case "update_empresa": {
        const { connection: _conn, idempresa, ...data } = args;
        result = await fsClient.put(`/empresas/${pathId(idempresa)}`, data, connection);
        break;
      }
      case "delete_empresa": {
        result = await fsClient.delete(`/empresas/${pathId(args.idempresa)}`, connection);
        break;
      }
      case "create_estadodocumento": {
        const { connection: _conn, ...data } = args;
        result = await fsClient.post("/estadodocumentos", data, connection);
        break;
      }
      case "update_estadodocumento": {
        const { connection: _conn, idestado, ...data } = args;
        result = await fsClient.put(`/estadodocumentos/${pathId(idestado)}`, data, connection);
        break;
      }
      case "delete_estadodocumento": {
        result = await fsClient.delete(`/estadodocumentos/${pathId(args.idestado)}`, connection);
        break;
      }
      case "create_agenciatransporte": {
        const { connection: _conn, ...data } = args;
        result = await fsClient.post("/agenciatransportes", data, connection);
        break;
      }
      case "update_agenciatransporte": {
        const { connection: _conn, codtrans, ...data } = args;
        result = await fsClient.put(`/agenciatransportes/${pathCode(codtrans, "codtrans")}`, data, connection);
        break;
      }
      case "delete_agenciatransporte": {
        result = await fsClient.delete(`/agenciatransportes/${pathCode(args.codtrans, "codtrans")}`, connection);
        break;
      }
      case "create_identificadorfiscal": {
        const { connection: _conn, ...data } = args;
        result = await fsClient.post("/identificadorfiscales", data, connection);
        break;
      }
      case "update_identificadorfiscal": {
        const { connection: _conn, tipoidfiscal, ...data } = args;
        result = await fsClient.put(`/identificadorfiscales/${pathCode(tipoidfiscal, "tipoidfiscal")}`, data, connection);
        break;
      }
      case "delete_identificadorfiscal": {
        result = await fsClient.delete(`/identificadorfiscales/${pathCode(args.tipoidfiscal, "tipoidfiscal")}`, connection);
        break;
      }
      case "create_secuenciadocumento": {
        const { connection: _conn, ...data } = args;
        result = await fsClient.post("/secuenciadocumentos", data, connection);
        break;
      }
      case "update_secuenciadocumento": {
        const { connection: _conn, idsecuencia, ...data } = args;
        result = await fsClient.put(`/secuenciadocumentos/${pathId(idsecuencia)}`, data, connection);
        break;
      }
      case "delete_secuenciadocumento": {
        result = await fsClient.delete(`/secuenciadocumentos/${pathId(args.idsecuencia)}`, connection);
        break;
      }
      default:
        return null;
    }
    return {
      content: [
        {
          type: "text",
          text: JSON.stringify(result, null, 2)
        }
      ]
    };
  } catch (error2) {
    const errorMessage = error2 instanceof Error ? error2.message : String(error2);
    return {
      content: [
        {
          type: "text",
          text: JSON.stringify({ error: errorMessage }, null, 2)
        }
      ],
      isError: true
    };
  }
}

